-- This migration re-applies the sections data now that the column exists.
UPDATE blog
SET
    status               = 'PUBLISHED',
    visibility           = 'PUBLIC',
    reading_time_minutes = 8,
    image_url            = 'https://images.pexels.com/photos/3938022/pexels-photo-3938022.jpeg?auto=compress&cs=tinysrgb&w=1200',
    sections             = '[{"type":"intro","title":"","content":"Food safety is a critical aspect of public health, requiring rigorous laboratory testing to identify and confirm the presence of foodborne pathogens. Biochemical confirmatory tests play a vital role in accurately identifying organisms such as Escherichia coli, Salmonella, Listeria monocytogenes, Vibrio species, and Bacillus cereus."},{"type":"text","title":"1. Escherichia coli (E. coli)","content":"Gram-negative short rods, non-spore-forming, motile via peritrichous flagella. Facultative anaerobe. Produces metallic green sheen on EMB agar and pink colonies on MacConkey agar (lactose fermenter)."},{"type":"table","title":"IMViC Biochemical Profile","headers":["Test","Result","Notes"],"rows":[["Indole","Positive (+)","Tryptophanase activity"],["Methyl Red (MR)","Positive (+)","Mixed acid fermentation"],["Voges-Proskauer (VP)","Negative (-)","No acetoin production"],["Citrate (Simmons)","Negative (-)","Cannot use citrate as sole carbon source"],["TSI Slant / Butt","Acid / Acid + Gas","Lactose and glucose fermentation with CO2"],["Urease","Negative (-)","Distinguishes from Proteus spp."]]},{"type":"text","title":"2. Salmonella spp.","content":"Gram-negative rods, non-spore-forming, usually motile. Colourless colonies on MacConkey agar (non-lactose fermenter). Black-centred colonies on XLD agar due to H2S production."},{"type":"bullets","title":"Key Biochemical Results","items":["H2S production: Positive on TSI — black precipitate in butt","Urease: Negative (key distinction from Proteus)","Lysine decarboxylase: Positive","Indole: Negative","Citrate: Usually positive","Serological confirmation: Agglutination with polyvalent O antiserum"]},{"type":"text","title":"3. Listeria monocytogenes","content":"Small Gram-positive rods, non-spore-forming, with characteristic tumbling motility at 25°C. Produces narrow zone of beta-hemolysis on sheep blood agar."},{"type":"callout","title":"CAMP Test","content":"Enhanced hemolysis (arrowhead zone) adjacent to Staphylococcus aureus streak — hallmark confirmatory result for Listeria monocytogenes. Negative with Rhodococcus equi (used to differentiate from L. ivanovii)."},{"type":"table","title":"Common Biochemical Tests — Quick Reference","headers":["Test","Principle","Positive Result Indicator"],"rows":[["IMViC (Indole)","Tryptophan to Indole via tryptophanase","Red ring (Kovacs reagent)"],["IMViC (MR)","Mixed acid fermentation lowers pH","Red colour after MR addition"],["TSI Agar","Sugar fermentation + H2S","Slant/butt colour change + blackening"],["Urease","Urea hydrolysis releases NH3","Phenol red turns pink/magenta"],["Oxidase","Cytochrome c oxidase activity","Purple colour within 10 seconds"],["Coagulase","Fibrinogen to Fibrin clot","Clot formation in tube test"]]},{"type":"faq","title":"Frequently Asked Questions","items":[{"question":"Why are biochemical tests necessary after culture isolation?","answer":"Morphological appearance alone is insufficient to identify foodborne pathogens at the species level. Biochemical tests confirm metabolic properties unique to each organism, ensuring accurate, reproducible, and legally defensible results that meet ISO 11290, ISO 6579, and ISO 6888 standards."},{"question":"How long do confirmatory tests take?","answer":"Most standard biochemical tests require 18-24 hours of incubation. Rapid automated systems (API 20E strips, VITEK 2, MALDI-TOF MS) can deliver reliable results in 4-8 hours."},{"question":"What is the gold standard for final confirmation?","answer":"Serological typing combined with biochemical profiling remains the regulatory gold standard. Molecular methods such as real-time PCR and whole-genome sequencing (WGS) are increasingly used for outbreak investigations."}]}]'
WHERE url_slug = 'biochemical-confirmatory-tests-for-foodborne-pathogens';
